//! PyTorch parity for `XlmRobertaModel::from_pretrained("FacebookAI/xlm-roberta-base")`.
//!
//! Loads the fixture generated by `flodl-hf/scripts/parity_xlm_roberta.py`
//! (`fdl flodl-hf parity xlm-roberta`) and compares flodl's
//! `pooler_output` against the Python `XLMRobertaModel` reference on
//! the same pinned multilingual input (FLORES-200 devtest row 0 across
//! 7 scripts). Same shape as `bert_parity.rs` — `FacebookAI/xlm-roberta-base`
//! ships pooler weights as `roberta.pooler.dense.{weight,bias}`, and
//! `XlmRobertaModel::from_pretrained` returns the with-pooler graph
//! dynamically when those weights are present.
//!
//! Note: `position_ids` is NOT an input here — XLM-RoBERTa's embeddings
//! compute it internally from `input_ids`. The graph takes 3 named
//! inputs: `input_ids`, `token_type_ids`, `attention_mask`.
//!
//! `_live` — pulls the real `FacebookAI/xlm-roberta-base` weights from the Hub.
//! Run with `fdl test-live`.

use std::path::Path;

use safetensors::SafeTensors;

use flodl::nn::Module;
use flodl::{Device, Tensor, Variable};
use flodl_hf::models::bert::build_extended_attention_mask;
use flodl_hf::models::xlm_roberta::XlmRobertaModel;

const FIXTURE: &str = "tests/fixtures/xlm_roberta_base_parity.safetensors";

/// Same 1e-5 budget as base-BERT and RoBERTa: `FacebookAI/xlm-roberta-base` ships
/// `hidden_act="gelu"` (erf form), so there's no `gelu_new` SIMD
/// compounding. Same libtorch kernels, same expected agreement, and
/// the pooler's `tanh` saturates the residual encoder noise.
const POOLER_TOL: f32 = 1e-5;

mod parity_common;
use parity_common::{max_abs_diff, parse_f32, parse_i64, shape_i64};

#[test]
#[ignore = "network + ~1.1GB cache write"]
fn xlm_roberta_parity_vs_pytorch_live() {
    let dev = Device::CPU;

    let bytes = std::fs::read(Path::new(FIXTURE)).unwrap_or_else(|e| {
        panic!(
            "reading {FIXTURE}: {e} \
             (run `fdl flodl-hf parity xlm-roberta` to regenerate)"
        )
    });
    let st = SafeTensors::deserialize(&bytes).expect("parse parity fixture");

    let ids = st.tensor("inputs.input_ids").unwrap();
    let tt = st.tensor("inputs.token_type_ids").unwrap();
    let mk = st.tensor("inputs.attention_mask").unwrap();
    let pooler_ref = st.tensor("outputs.pooler_output").unwrap();

    let input_ids = Variable::new(
        Tensor::from_i64(&parse_i64(&ids), &shape_i64(&ids), dev).unwrap(),
        false,
    );
    let token_type_ids = Variable::new(
        Tensor::from_i64(&parse_i64(&tt), &shape_i64(&tt), dev).unwrap(),
        false,
    );
    let mask_flat_f32: Vec<f32> = parse_i64(&mk).iter().map(|&x| x as f32).collect();
    let mask_flat = Tensor::from_f32(&mask_flat_f32, &shape_i64(&mk), dev).unwrap();
    let attention_mask = Variable::new(build_extended_attention_mask(&mask_flat).unwrap(), false);

    let pooler_ref_data = parse_f32(&pooler_ref);
    let pooler_ref_shape = shape_i64(&pooler_ref);

    let graph = XlmRobertaModel::from_pretrained("FacebookAI/xlm-roberta-base").unwrap();
    graph.eval();

    let out = graph
        .forward_multi(&[input_ids, token_type_ids, attention_mask])
        .unwrap();
    assert_eq!(
        out.shape(),
        pooler_ref_shape,
        "pooler_output shape mismatch"
    );

    let actual = out.data().to_f32_vec().unwrap();
    let diff = max_abs_diff(&actual, &pooler_ref_data);
    eprintln!(
        "FacebookAI/xlm-roberta-base pooler_output max_abs_diff = {diff:.3e} (tol {POOLER_TOL:.0e})"
    );
    assert!(
        diff <= POOLER_TOL,
        "pooler_output parity: max_abs_diff = {diff:.3e} exceeds tol {POOLER_TOL:.0e}",
    );
}
